        result = subprocess.run(['powershell', '-NoProfile', '-NonInteractive', '-Command', 'Get-CimInstance -ClassName Win32_OperatingSystem | Select-Object -Property FreePhysicalMemory, TotalVisibleMemorySize | ForEach-Object { $usagePercent = 100 - ($_.FreePhysicalMemory / $_.TotalVisibleMemorySize * 100); $usagePercent }'], capture_output=True, text=True)
        if result.returncode == 0:
            return {'status': float(result.stdout.strip())}
        else:
            return {'status': '未実装'}
    except Exception as e:
        return {'status': '未実装'}
